// Retail: Fable.exe (TLC, VC7.1) function @ 0x00C55B70, length 268 bytes.
// Callees: none. Caller: the landed CScreenEffectOwner_00c55c80::Reset @ 0x00C55C80 (`Reset(1)`), plus 0xC55D18/0xC562DB/0xC56455.
// The manifest label "CScreenEffectPriorityStack::Reset" is propagated: the body sits in the OpenAL wrapper TU (0xC55xxx) and the
// flag at +0x104 is CAudioContext::UseALGetProcAddress (landed EAXSet 0x00C558A0 model). Shape: one zero register (eax) serves both the
// `force` compare and the 51 dword stores; `if (force || flag)` gives `cmp dl,al ; jne` then `cmp [ecx+104h],al ; je ret`.
// The entry points are separate members (an array cleared by a loop would become `rep stosd`).
struct CAudioContext {
    void*         __vftable;
    void*         Module;                    // +0x04
    unsigned char _pad08[0x24];
    void*         pfnEntry_2c;               // +0x2c
